'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts (orders + inventory + network).
// Abstraction: three order ids a, b, c. Each order has at most one message in
// transit at a time (Reserve -> Reserved|OutOfStock -> [Release]), so the
// network is modelled as one message slot per order: orders[o].msg.
//   status: 'none' (never placed) | pending | confirmed | rejected | cancelling | cancelled
//   msg:    'none' | 'Reserve' | 'Reserved' | 'OutOfStock' | 'Release'

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CAPACITY = 3;
const EMPTY = { status: 'none', qty: 0, msg: 'none' };
const INITIAL_STATE = {
  available: 1,
  reserved: 0,
  orders: { a: { ...EMPTY }, b: { ...EMPTY }, c: { ...EMPTY } },
};

const ORDER_IDS = ['a', 'b', 'c'];
const orderDomain = ORDER_IDS.map((order) => ({ order }));

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      orders: { type: 'object' },
    },
    actions: {
      PLACE: {
        action: (data = {}) => ({ ...data }),
        schema: { order: { type: 'string' }, qty: { type: 'number' } },
        domain: ORDER_IDS.flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
      },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: { order: { type: 'string' } }, domain: orderDomain },
      RESTOCK: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { order: { type: 'string' } }, domain: orderDomain },
    },
    acceptors: {
