import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.deepEqual(await h.inFlight(), []);
  assert.equal(await h.order('x'), null);
});

test('restock up to 3 units', async () => {
  const h = await createHost();
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  const r = await h.restock();
  assert.equal(r.ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0 });
});

test('place validation', async () => {
  const h = await createHost();
  for (const q of [0, 3, 1.5, -1]) assert.equal((await h.place('a', q)).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
});

test('confirm then cancel releases units', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  assert.equal((await h.restock()).ok, true);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a')).status, 'cancelled');
  const [m] = await h.inFlight();
  assert.equal(m.action, 'Release');
  assert.deepEqual(m.data, { qty: 1 });
  await h.deliver(m.id);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('out of stock rejects', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel pending, reserved answer arrives later, units given back', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.deliver((await h.inFlight())[0].id); // Reserve
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a')).status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('cancel pending before reserve arrives, out of stock', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('unknown order commands are refused', async () => {
  const h = await createHost();
  assert.equal((await h.cancel('zz')).ok, false);
});

test('messages may be delivered out of order', async () => {
  const h = await createHost();
  await h.restock();
  await h.place('a', 1);
  await h.place('b', 2);
  const [ma, mb] = await h.inFlight();
  await h.deliver(mb.id); // b reserves 2
  await h.deliver(ma.id); // a out of stock
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'rejected');
  assert.equal((await h.order('b')).status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
});

