// Capture NDJSON trace windows {pre, action, data, post} from the real
// implementation (src/host.impl.ts), projected onto the contract's state keys.
// Usage: node spec/capture.mjs [scenarios=40] [steps=40]
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { System } from '../src/host.impl.ts';

const ORDER_IDS = ['a', 'b', 'c'];
const outDir = new URL('./traces/', import.meta.url);

function project(sys) {
  const snap = sys.snapshot();
  const orders = {};
  for (const id of ORDER_IDS) {
    const o = snap.orders[id];
    const msgs = snap.inFlight.filter((m) => m.from === id || m.to === id);
    if (msgs.length > 1) throw new Error(`order ${id} has ${msgs.length} messages in transit — spec abstraction broken`);
    orders[id] = { status: o ? o.status : 'none', qty: o ? o.qty : 0, msg: msgs.length ? msgs[0].action : 'none' };
  }
  return { available: snap.available, reserved: snap.reserved, orders };
}

// Small deterministic PRNG so the corpus is reproducible.
function rng(seed) {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
}

async function step(sys, action, data) {
  const pre = project(sys);
  if (action === 'PLACE') await sys.place(data.order, data.qty);
  else if (action === 'CANCEL') await sys.cancel(data.order);
  else if (action === 'EXPIRE') await sys.expire(data.order);
  else if (action === 'RESTOCK') await sys.restock();
  else if (action === 'DELIVER') {
    const m = (await sys.inFlight()).find((x) => x.from === data.order || x.to === data.order);
    if (m) await sys.deliver(m.id);
  }
  return { pre, action, data, post: project(sys) };
}

const scenarios = Number(process.argv[2] || 40);
const steps = Number(process.argv[3] || 40);
rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
let total = 0;
for (let n = 0; n < scenarios; n++) {
  const r = rng(n + 1);
  const pick = (xs) => xs[Math.floor(r() * xs.length)];
  const sys = new System();
  const lines = [];
  for (let i = 0; i < steps; i++) {
    const kind = pick(['PLACE', 'PLACE', 'CANCEL', 'EXPIRE', 'RESTOCK', 'DELIVER', 'DELIVER', 'DELIVER']);
    const data = kind === 'PLACE' ? { order: pick(ORDER_IDS), qty: pick([0, 1, 2, 2, 1, 3]) }
      : kind === 'RESTOCK' ? {} : { order: pick(ORDER_IDS) };
    lines.push(JSON.stringify(await step(sys, kind, data)));
  }
  total += lines.length;
  writeFileSync(new URL(`s${String(n).padStart(3, '0')}.ndjson`, outDir), lines.join('\n') + '\n');
}
console.log(`captured ${total} windows in ${scenarios} traces`);

