  if (action === 'PLACE') await sys.place(data.order, data.qty);
  else if (action === 'CANCEL') await sys.cancel(data.order);
  else if (action === 'EXPIRE') await sys.expire(data.order);
  else if (action === 'RESTOCK') await sys.restock();
  else if (action === 'CLOSE') await sys.close();
  else if (action === 'OPEN') await sys.open();
  else if (action === 'DELIVER') {
    const m = (await sys.inFlight()).find((x) => x.from === data.order || x.to === data.order);
    if (m) await sys.deliver(m.id);
  }
  return { pre, action, data, post: project(sys) };
}

const scenarios = Number(process.argv[2] || 40);
const steps = Number(process.argv[3] || 40);
rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
let total = 0;
for (let n = 0; n < scenarios; n++) {
  const r = rng(n + 1);
  const pick = (xs) => xs[Math.floor(r() * xs.length)];
  const sys = new System();
  const lines = [];
  for (let i = 0; i < steps; i++) {
    const kind = pick(['PLACE', 'PLACE', 'CANCEL', 'EXPIRE', 'RESTOCK', 'CLOSE', 'OPEN', 'DELIVER', 'DELIVER', 'DELIVER']);
    const data = kind === 'PLACE' ? { order: pick(ORDER_IDS), qty: pick([0, 1, 2, 2, 1, 3]) }
      : ['RESTOCK', 'CLOSE', 'OPEN'].includes(kind) ? {} : { order: pick(ORDER_IDS) };
    lines.push(JSON.stringify(await step(sys, kind, data)));
  }
  total += lines.length;
  writeFileSync(new URL(`s${String(n).padStart(3, '0')}.ndjson`, outDir), lines.join('\n') + '\n');
}
console.log(`captured ${total} windows in ${scenarios} traces`);

