test('close and open toggle, each refused when already in that state', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('closed inventory answers OutOfStock and refuses restock', async () => {
  const h = await createHost();
  await h.close();
  assert.equal((await h.restock()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  await h.open();
  assert.deepEqual(await h.restock(), { ok: true });
});

test('closing is decided when Reserve arrives, not when placed', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.close();
  await h.open();
  await h.deliverAll();
  assert.equal((await h.order('a')).status, 'confirmed');
  await h.place('b', 1);
  await h.close();
  await h.deliverAll();
  assert.equal((await h.order('b')).status, 'rejected');
});

test('closed inventory still takes a Release', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.deliverAll();
  await h.close();
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  await h.place('c', 1);
  await h.cancel('c');
  await h.deliverAll();
  assert.equal((await h.order('c')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
});
