'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts (orders + inventory + network).
// Abstraction: three order ids a, b, c. Per order, the network holds
//   msg: the one request/reply in transit — 'none' | 'Reserve' | 'Reserved' | 'OutOfStock'
//   rel: the qtys of the Release messages in transit from this order, in send order
//        (reduce then cancel/expire can put two in transit at once).
//   status: 'none' (never placed) | pending | confirmed | rejected | cancelling | cancelled | expired

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CAPACITY = 3;
const EMPTY = { status: 'none', qty: 0, msg: 'none', rel: [] };
const INITIAL_STATE = {
  available: 1,
  reserved: 0,
  orders: { a: EMPTY, b: EMPTY, c: EMPTY },
  open: true,
};

const ORDER_IDS = ['a', 'b', 'c'];
const orderDomain = ORDER_IDS.map((order) => ({ order }));
const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });
const byOrder = { order: { type: 'string' } };

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      orders: { type: 'object' },
      open: { type: 'boolean' },
    },
    actions: {
      PLACE: intent(
        { order: { type: 'string' }, qty: { type: 'number' } },
        ORDER_IDS.flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
      ),
      CANCEL: intent(byOrder, orderDomain),
      EXPIRE: intent(byOrder, orderDomain),
      REDUCE: intent(byOrder, orderDomain),
      RESTOCK: intent({}, [{}]),
      CLOSE: intent({}, [{}]),
      OPEN: intent({}, [{}]),
      DELIVER: intent(byOrder, orderDomain),
      DELIVER_RELEASE: intent(byOrder, orderDomain),
    },
    acceptors: {
      PLACE: (model) => (p, { reject, next, unchanged }) => {
        if (p.qty !== 1 && p.qty !== 2) return reject('qty-must-be-1-or-2');
        const o = model.orders[p.order];
        if (o.status !== 'none') return reject('order-exists');
        next.orders = { ...model.orders, [p.order]: { status: 'pending', qty: p.qty, msg: 'Reserve', rel: [] } };
        unchanged('available', 'reserved', 'open');
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o.status === 'none') return reject('no-such-order');
        if (o.status === 'confirmed') {
          next.orders = { ...model.orders, [p.order]: { ...o, status: 'cancelled', rel: [...o.rel, o.qty] } };
        } else if (o.status === 'pending') {
          next.orders = { ...model.orders, [p.order]: { ...o, status: 'cancelling' } };
        } else {
          return reject('cancel-not-allowed');
        }
        unchanged('available', 'reserved', 'open');
      },
      EXPIRE: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o.status === 'none') return reject('no-such-order');
        if (o.status !== 'confirmed') return reject('expire-not-allowed');
        next.orders = { ...model.orders, [p.order]: { ...o, status: 'expired', rel: [...o.rel, o.qty] } };
        unchanged('available', 'reserved', 'open');
      },
      REDUCE: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o.status === 'none') return reject('no-such-order');
        if (o.status !== 'confirmed' || o.qty !== 2) return reject('reduce-not-allowed');
        next.orders = { ...model.orders, [p.order]: { ...o, qty: 1, rel: [...o.rel, 1] } };
        unchanged('available', 'reserved', 'open');
      },
      CLOSE: (model) => (p, { reject, next, unchanged }) => {
        if (!model.open) return reject('already-closed');
        next.open = false;
        unchanged('available', 'reserved', 'orders');
      },
      OPEN: (model) => (p, { reject, next, unchanged }) => {
        if (model.open) return reject('already-open');
        next.open = true;
        unchanged('available', 'reserved', 'orders');
      },
      RESTOCK: (model) => (p, { reject, next, unchanged }) => {
        if (!model.open) return reject('restock-while-closed');
        if (model.available + model.reserved >= CAPACITY) return reject('inventory-full');
        next.available = model.available + 1;
        unchanged('reserved', 'orders', 'open');
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o.msg === 'none') return reject('no-message-in-transit');
        if (o.msg === 'Reserve') {
          if (model.open && model.available >= o.qty) {
            next.available = model.available - o.qty;
            next.reserved = model.reserved + o.qty;
            next.orders = { ...model.orders, [p.order]: { ...o, msg: 'Reserved' } };
            unchanged('open');
          } else {
            next.orders = { ...model.orders, [p.order]: { ...o, msg: 'OutOfStock' } };
            unchanged('available', 'reserved', 'open');
          }
        } else if (o.msg === 'Reserved') {
          let n;
          if (o.status === 'pending') n = { ...o, status: 'confirmed', msg: 'none' };
          else if (o.status === 'cancelling') n = { ...o, status: 'cancelled', msg: 'none', rel: [...o.rel, o.qty] };
          else n = { ...o, msg: 'none' };
          next.orders = { ...model.orders, [p.order]: n };
          unchanged('available', 'reserved', 'open');
        } else {
          // OutOfStock
          let status = o.status;
          if (o.status === 'pending') status = 'rejected';
          else if (o.status === 'cancelling') status = 'cancelled';
          next.orders = { ...model.orders, [p.order]: { ...o, status, msg: 'none' } };
          unchanged('available', 'reserved', 'open');
        }
      },
      DELIVER_RELEASE: (model) => (p, { reject, next, unchanged }) => {
        const o = model.orders[p.order];
        if (o.rel.length === 0) return reject('no-release-in-transit');
        const qty = o.rel[0];
        next.available = model.available + qty;
        next.reserved = model.reserved - qty;
        next.orders = { ...model.orders, [p.order]: { ...o, rel: o.rel.slice(1) } };
        unchanged('open');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(JSON.parse(JSON.stringify(INITIAL_STATE))); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  REDUCE: (data = {}) => intents.REDUCE(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  CLOSE: (data = {}) => intents.CLOSE(data),
  OPEN: (data = {}) => intents.OPEN(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
  DELIVER_RELEASE: (data = {}) => intents.DELIVER_RELEASE(data),
};

module.exports = { instance, init, actions, getState, setState };

