// Rules the brief requires, over the spec state { available, reserved, orders }.
const CAPACITY = 3;
const orders = (s) => Object.values(s.orders);
const sum = (xs) => xs.reduce((a, b) => a + b, 0);

// Units held for an order: its Reserve succeeded and its Release has not arrived.
const holds = (o) =>
  (o.status === 'confirmed' && o.msg === 'none') || o.msg === 'Reserved' || o.msg === 'Release';

const ALLOWED = new Set([
  'none>pending',
  'pending>confirmed', 'pending>rejected', 'pending>cancelling',
  'confirmed>cancelled', 'cancelling>cancelled',
  'confirmed>expired',
]);

export const stateInvariants = [
  { name: 'stock-non-negative', pred: (s) => s.available >= 0 && s.reserved >= 0 },
  { name: 'capacity', pred: (s) => s.available + s.reserved <= CAPACITY },
  {
    name: 'reserved-equals-units-held',
    pred: (s) => s.reserved === sum(orders(s).filter(holds).map((o) => o.qty)),
  },
  {
    name: 'quiescent-reserved-equals-confirmed',
    pred: (s) => orders(s).some((o) => o.msg !== 'none')
