  },
  {
    name: 'confirmed-has-units-reserved',
    pred: (s) => orders(s).every((o) => o.status !== 'confirmed' || o.msg === 'none'),
  },
  {
    name: 'finished-orders-hold-nothing-once-settled',
    pred: (s) => orders(s).every((o) =>
      !['rejected', 'cancelled', 'expired'].includes(o.status) || o.msg === 'Release' || !holds(o)),
  },
  {
    name: 'expired-only-releasing-or-settled',
    pred: (s) => orders(s).every((o) => o.status !== 'expired' || o.msg === 'Release' || o.msg === 'none'),
  },
  {
    name: 'qty-valid',
    pred: (s) => orders(s).every((o) => (o.status === 'none' ? o.qty === 0 : o.qty === 1 || o.qty === 2)),
  },
];

