// Rules the brief requires, over the spec state { available, reserved, orders, open }.
const CAPACITY = 3;
const orders = (s) => Object.values(s.orders);
const sum = (xs) => xs.reduce((a, b) => a + b, 0);

// Units the order itself still holds (excluding Releases already in transit):
// its Reserve succeeded and it has not given them back.
const kept = (o) => ((o.status === 'confirmed' && o.msg === 'none') || o.msg === 'Reserved' ? o.qty : 0);
// Units reserved on the order's behalf: kept, plus those in Releases not yet arrived.
const held = (o) => kept(o) + sum(o.rel);
const inTransit = (s) => orders(s).some((o) => o.msg !== 'none' || o.rel.length > 0);

const ALLOWED = new Set([
  'none>pending',
  'pending>confirmed', 'pending>rejected', 'pending>cancelling',
  'confirmed>cancelled', 'cancelling>cancelled',
  'confirmed>expired',
]);

export const stateInvariants = [
  { name: 'stock-non-negative', pred: (s) => s.available >= 0 && s.reserved >= 0 },
  { name: 'capacity', pred: (s) => s.available + s.reserved <= CAPACITY },
  {
    name: 'reserved-equals-units-held',
    pred: (s) => s.reserved === sum(orders(s).map(held)),
  },
  {
    name: 'quiescent-reserved-equals-confirmed',
    pred: (s) => inTransit(s)
      || s.reserved === sum(orders(s).filter((o) => o.status === 'confirmed').map((o) => o.qty)),
  },
  {
    name: 'confirmed-has-its-units-reserved',
    pred: (s) => orders(s).every((o) => o.status !== 'confirmed' || (o.msg === 'none' && kept(o) === o.qty)),
  },
  {
    name: 'finished-orders-keep-nothing',
    pred: (s) => orders(s).every((o) => !['rejected', 'cancelled', 'expired'].includes(o.status) || kept(o) === 0),
  },
  {
    name: 'releases-only-from-orders-that-had-units',
    pred: (s) => orders(s).every((o) => o.rel.length === 0 || ['confirmed', 'cancelled', 'expired'].includes(o.status)),
  },
  {
    name: 'qty-valid',
    pred: (s) => orders(s).every((o) => (o.status === 'none' ? o.qty === 0 : o.qty === 1 || o.qty === 2)),
  },
];

export const transitionInvariants = [
  {
    name: 'status-moves-only-along-allowed-edges',
    pred: (pre, action, data, post) => Object.keys(pre.orders).every((k) => {
      const a = pre.orders[k].status, b = post.orders[k].status;
      return a === b || ALLOWED.has(`${a}>${b}`);
    }),
  },
  {
    name: 'closed-inventory-reserves-nothing',
    pred: (pre, action, data, post) => pre.open || post.reserved <= pre.reserved,
  },
  {
    name: 'closed-inventory-refuses-restock',
    pred: (pre, action, data, post) => pre.open || action !== 'RESTOCK' || post.available === pre.available,
  },
  {
    name: 'closed-inventory-answers-out-of-stock',
    pred: (pre, action, data, post) => pre.open || action !== 'DELIVER'
      || pre.orders[data.order].msg !== 'Reserve' || post.orders[data.order].msg === 'OutOfStock',
  },
  {
    name: 'release-always-taken',
    pred: (pre, action, data, post) => action !== 'DELIVER_RELEASE' || pre.orders[data.order].rel.length === 0
      || post.reserved === pre.reserved - pre.orders[data.order].rel[0],
  },
  {
    name: 'only-close-and-open-toggle-open',
    pred: (pre, action, data, post) => pre.open === post.open
      || (action === 'CLOSE' && pre.open && !post.open) || (action === 'OPEN' && !pre.open && post.open),
  },
  {
    name: 'expired-accepts-no-command',
    pred: (pre, action, data, post) => action.startsWith('DELIVER') || !data.order
      || pre.orders[data.order].status !== 'expired'
      || JSON.stringify(pre) === JSON.stringify(post),
  },
  {
    name: 'units-never-lost-or-invented',
    pred: (pre, action, data, post) => {
      const d = post.available + post.reserved - (pre.available + pre.reserved);
      return action === 'RESTOCK' ? d === 1 || d === 0 : d === 0;
    },
  },
  {
    name: 'qty-changes-only-by-reduce-2-to-1',
    pred: (pre, action, data, post) => Object.keys(pre.orders).every((k) => {
      const a = pre.orders[k], b = post.orders[k];
      return a.status === 'none' || a.qty === b.qty
        || (action === 'REDUCE' && k === data.order && a.status === 'confirmed' && a.qty === 2 && b.qty === 1);
    }),
  },
  {
    name: 'reduce-keeps-confirmed-and-releases-one',
    pred: (pre, action, data, post) => {
      if (action !== 'REDUCE') return true;
      const a = pre.orders[data.order], b = post.orders[data.order];
      if (a.qty === b.qty) return JSON.stringify(pre) === JSON.stringify(post); // refused
      return b.status === 'confirmed' && b.rel.length === a.rel.length + 1 && b.rel[b.rel.length - 1] === 1;
    },
  },
];

