// Negative control: write seeded-bug copies of the spec into spec/controls/mutants/.
// Each must FAIL replay against the captured traces and/or the model check.
// Usage: node spec/controls/make-mutants.mjs
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';

const src = readFileSync(new URL('../orders.spec.cjs', import.meta.url), 'utf8');
const MUTANTS = {
  // A cancelling order that learns its units were reserved forgets to release them.
  'no-release-on-late-reserved': [
    "n = { ...o, status: 'cancelled', msg: 'none', rel: [...o.rel, o.qty] }",
    "n = { ...o, status: 'cancelled', msg: 'none' }",
  ],
  // The inventory reserves even when too few units are available.
  'reserve-without-stock': ['if (model.open && model.available >= o.qty)', 'if (model.open && model.available >= 0)'],
  // Expiring a confirmed order forgets to give its units back.
  'expire-without-release': [
    "status: 'expired', rel: [...o.rel, o.qty] }",
    "status: 'expired' }",
  ],
  // A closed inventory still reserves.
  'reserve-while-closed': ['if (model.open && model.available >= o.qty)', 'if (model.available >= o.qty)'],
  // A closed inventory still restocks.
  'restock-while-closed': ["if (!model.open) return reject('restock-while-closed');", ''],
  // Restock ignores the capacity limit.
  'restock-unbounded': ['>= CAPACITY) return reject', '>= CAPACITY + 1) return reject'],
  // Reduce lowers the qty but sends no Release (the unit is stranded in reserved).
  'reduce-without-release': ['{ ...o, qty: 1, rel: [...o.rel, 1] }', '{ ...o, qty: 1 }'],
  // Cancel after a reduce releases the ORIGINAL 2 units (double release).
  'cancel-releases-original-qty': [
    "status: 'cancelled', rel: [...o.rel, o.qty] }",
    "status: 'cancelled', rel: [...o.rel, 2] }",
  ],
};

const dir = new URL('./mutants/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!src.includes(from)) throw new Error(`mutation ${name}: anchor not found`);
  writeFileSync(new URL(`${name}.cjs`, dir), src.replace(from, to));
  console.log(`wrote mutants/${name}.cjs`);
}

