// Negative control, model-check half: every mutant must violate at least one invariant.
// Usage: node spec/controls/check-mutants.mjs   (after make-mutants.mjs)
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { check, loadSpec } from '../../tools/polygraph/scripts/check.mjs';
import * as invariants from '../invariants.mjs';

const dir = new URL('./mutants/', import.meta.url);
const contract = JSON.parse(readFileSync(new URL('../contract.json', import.meta.url), 'utf8'));
let survivors = 0;
for (const f of readdirSync(dir).filter((x) => x.endsWith('.cjs')).sort()) {
  const r = check({ specModule: loadSpec(fileURLToPath(new URL(f, dir))), contract, invariants });
  const names = [...new Set((r.violations || []).map((v) => v.name || v.invariant))];
  if (names.length === 0) survivors++;
  console.log(`${names.length ? 'killed  ' : 'SURVIVED'} ${f}  ${names.join(', ')}`);
}
process.exit(survivors ? 1 : 0);

